class ComputeIsocontours(Node):

    def __init__(self, parent_node_id : str, num_contours : int):
        if correctness_checks_on():
            if num_contours < 1:
                raise Exception("Number of contours must be positive.")

        super().__init__(parent_node_id, types.Scalar, types.Contours, locals())

        self.num_contours = num_contours

    @classmethod
    def chat_description(cls):
        return "queued computing isocontours"

    @classmethod
    def description(cls):
        return 'Computes a certain number of isocontours uniformly distributed by function value for a scalar field.'

    @classmethod
    def param_descriptions(cls):
        return {'parent_node_id': 'The id of a node of type scalar corresponding to the scalar field '
                           'whose contours we are computing.',
         'num_contours': 'The number of contours that are to be computed.'}

    def _evaluation_logic(self, parent_data, time_step):
        scalar_vtk = servermanager.Fetch(parent_data.data)
        numPoints = scalar_vtk.GetNumberOfPoints()
        scalar_array = scalar_vtk.GetPointData().GetArray("Scalars_")
        scalar_range = scalar_array.GetRange()
        dimensions = scalar_vtk.GetDimensions()

        skip = int(numPoints/1000000)
        if skip == 0:
            skip = 1

        values = []
        for i in range(0, numPoints, skip):
            values.append(scalar_array.GetTuple1(i))

        numSampled = len(values)
        values.sort()

        contour_values = []

        for n in range(self.num_contours):
            query_idx = int( (n+1) / (self.num_contours+1) * numSampled )
            contour_values.append( values[query_idx] )

        print(contour_values)

        contours = Contour(Input=parent_data.data)
        contours.ContourBy = ['POINTS', 'Scalars_']
        contours.Isosurfaces = contour_values
        contours.PointMergeMethod = 'Uniform Binning'

        return types.Contours(contours, *scalar_range, dimensions)

